package com.oms.supplychain;
import com.oms.supplychain.service.wms.*;
import com.oms.supplychain.service.warehouse.impl.WarehouseWorkspaceService;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

class WmsOutboundServiceTest {
    static AnnotationConfigApplicationContext context;static JdbcTemplate jdbc;static WmsStore db;WmsOutboundService service;WmsConnections connections;WarehouseWorkspaceService warehouses;HttpServer server;long relation,connection;AtomicInteger creates=new AtomicInteger(),queries=new AtomicInteger();AtomicReference<Throwable> failure=new AtomicReference<>();String provider="QIMEN",responseMode="OK",queryMode="ACCEPT";
    @BeforeAll static void setup(){String url=System.getenv("PURCHASE_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/purchase_workspace_test?"));context=new AnnotationConfigApplicationContext(PurchaseWorkspaceTest.Config.class);jdbc=context.getBean(JdbcTemplate.class);db=context.getBean(WmsStore.class);}
    @AfterAll static void close(){if(context!=null)context.close();}
    @BeforeEach void seed() throws Exception {
        for(String table:Arrays.asList("wms_outbound_receipt_review","wms_outbound_waybill_lock","wms_outbound_receipt_package","wms_outbound_receipt_event","wms_outbound_task","wms_interaction_log","wms_inbound_task","wms_receipt_line","wms_receipt_event","wms_connection","purchase_event","purchase_line","no_tickets_goods","wms_tickets_goods","no_tickets","wms_tickets","po_info","supplier_info","wms_simulation_store_info","owner_warehouse","owner_info","wms_real_store_info"))jdbc.update("DELETE FROM "+table);
        connections=context.getBean(WmsConnections.class);ReflectionTestUtils.setField(connections,"encryptionKey",Base64.getEncoder().encodeToString(new byte[32]));warehouses=context.getBean(WarehouseWorkspaceService.class);WmsTenantRoutes routes=context.getBean(WmsTenantRoutes.class);service=new WmsOutboundService();ReflectionTestUtils.setField(service,"db",db);ReflectionTestUtils.setField(service,"connections",connections);ReflectionTestUtils.setField(service,"tenantRoutes",routes);ReflectionTestUtils.setField(service,"logs",context.getBean(WmsInteractionLog.class));ReflectionTestUtils.setField(service,"protocols",Arrays.asList(new QimenProtocol(),new JdHufuProtocol()));
        long owner=warehouses.save("QM","owner",map("ownerCode","O","ownerName","owner","isEnable",2)),store=warehouses.save("QM","realStore",map("realStoreCode","W","wmsName","warehouse","status",2,"wmsType",1));relation=warehouses.save("QM","ownerWarehouse",map("ownerId",owner,"realStoreId",store,"status",2));server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/router",this::handle);server.setExecutor(Executors.newCachedThreadPool());server.start();
    }
    @AfterEach void stop(){if(server!=null){server.stop(0);((ExecutorService)server.getExecutor()).shutdownNow();}jdbc.update("DELETE FROM wms_outbound_task");}
    void setupWarehouse(String provider){this.provider=provider;connection=connections.save("QM",map("name","fixture","provider",provider,"api_version","2.0","environment","TEST","endpoint","http://127.0.0.1:"+server.getAddress().getPort()+"/router","app_key","APP","customer_id","CUSTOMER","secret","fixture-secret","enabled",1));warehouses.save("QM","simulationStore",map("wmsSimulationCode","V","wmsSimulationName","virtual","inboundMode",2,"outboundMode",1,"status",2,"ownerWarehouseId",relation,"connectionId",connection,"externalWarehouse","EXT-W","externalOwner","EXT-O"));}
    Map<String,Object> payload(){Map<String,Object> p=map("shipment_id",1,"shipment_sn","FH_TEST","owner_code","O","real_store_code","W","platform_tid","12345","quantity",3,"warehouse_carrier_code","SF","carrier_name","express","create_time","2026-10-12 11:00:00","place_order_time","2026-10-11 10:00:00","operate_time","2026-10-12 10:00:00","shop_name","shop","seller_nick","seller","receiver",map("name","private-name","mobile","13812341234","province","北京市","city","北京市","area","海淀区","detailAddress","private-address","oaid","private-oaid"),"store_codes",Arrays.asList("V"),"lines",Arrays.asList(map("id",1,"sku_sn","A<&","goods_name","goods","quantity",3,"platform_oid","123450","store_code","V","batch_code","B001")));p.put("route",service.resolve("QM",p));return p;}
    void handle(com.sun.net.httpserver.HttpExchange exchange){try{
        String body=org.springframework.util.StreamUtils.copyToString(exchange.getRequestBody(),StandardCharsets.UTF_8);Map<String,String> params=new TreeMap<>();for(String pair:exchange.getRequestURI().getRawQuery().split("&")){String[] kv=pair.split("=",2);params.put(URLDecoder.decode(kv[0],"UTF-8"),URLDecoder.decode(kv[1],"UTF-8"));}assertEquals(QimenProtocol.sign(params,body,"fixture-secret"),params.get("sign"));assertTrue(body.contains("EXT-W")&&body.contains("EXT-O"));boolean create=params.get("method").endsWith(".create");if(create){creates.incrementAndGet();assertTrue(body.contains("JYCK")&&body.contains("SF")&&body.contains("B001")&&body.contains("private-oaid"));assertTrue(body.contains(provider.equals("QIMEN")?"A&lt;&amp;":"A<&"));}else queries.incrementAndGet();
        if(provider.equals("JD_HUFU"))assertEquals(create?"/router/deliveryOrderCreate":"/router/deliveryOrderQuery",exchange.getRequestURI().getPath());
        String flag=create&&Arrays.asList("FAIL","DUPLICATE").contains(responseMode)?"failure":"success",code=create&&"DUPLICATE".equals(responseMode)?"DUPLICATE":!create&&"NOT_FOUND".equals(queryMode)?"NOT_FOUND":"0",external=create&&"FAIL".equals(responseMode)?"":"EXT-1",state=create?"":queryMode;
        String response=provider.equals("QIMEN")?"<response><flag>"+flag+"</flag><code>"+code+"</code><message>result</message>"+(create?"<deliveryOrderId>"+external+"</deliveryOrderId>":"<deliveryOrder><deliveryOrderCode>FH_TEST</deliveryOrderCode><deliveryOrderId>EXT-1</deliveryOrderId><ownerCode>EXT-O</ownerCode><warehouseCode>EXT-W</warehouseCode><status>"+state+"</status></deliveryOrder>")+"</response>":db.encode(map("flag",flag,"code",code,"message","result",create?"deliveryOrderId":"deliveryOrder",create?external:map("deliveryOrderCode","FH_TEST","deliveryOrderId","EXT-1","ownerCode","EXT-O","warehouseCode","EXT-W","status",state)));
        if(create&&"MALFORMED".equals(responseMode))response="not a valid response";byte[] bytes=response.getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);
    }catch(Throwable e){failure.set(e);}finally{exchange.close();}}
    @Test void qimenSignedCreateIsIdempotentAndQueryDoesNotPostInventory(){setupWarehouse("QIMEN");Map<String,Object> p=payload();assertEquals("ACCEPTED",service.submit("QM",p,false).get("dispatch_state"));assertEquals("ACCEPTED",service.submit("QM",p,false).get("dispatch_state"));assertEquals(1,creates.get());assertEquals("ACCEPTED",service.query("QM","FH_TEST").get("dispatch_state"));assertEquals(1,queries.get());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM wms_receipt_line",Integer.class));assertNull(failure.get());String logs=jdbc.queryForObject("SELECT request_body FROM wms_interaction_log WHERE action='OUTBOUND_CREATE'",String.class);for(String value:Arrays.asList("private-name","13812341234","private-address","private-oaid","fixture-secret"))assertFalse(logs.contains(value));}
    @Test void hufuUsesDeliveryEndpointsAndJsonFields(){setupWarehouse("JD_HUFU");Map<String,Object> p=payload();assertEquals("ACCEPTED",service.submit("QM",p,false).get("dispatch_state"));assertEquals("ACCEPTED",service.query("QM","FH_TEST").get("dispatch_state"));assertEquals(1,creates.get());assertNull(failure.get());}
    @Test void malformedReplyStaysUnknownAndNotFoundNeverRecreates(){setupWarehouse("QIMEN");Map<String,Object> p=payload();responseMode="MALFORMED";assertEquals("UNKNOWN",service.submit("QM",p,false).get("dispatch_state"));assertEquals("UNKNOWN",service.submit("QM",p,true).get("dispatch_state"));assertEquals(1,creates.get());queryMode="NOT_FOUND";assertEquals("UNKNOWN",service.query("QM","FH_TEST").get("dispatch_state"));assertEquals(1,creates.get());queryMode="ACCEPT";assertEquals("ACCEPTED",service.query("QM","FH_TEST").get("dispatch_state"));}
    @Test void definitiveFailureNeedsExplicitRetryAndKeepsOneTask(){setupWarehouse("QIMEN");Map<String,Object> p=payload();responseMode="FAIL";assertEquals("FAILED",service.submit("QM",p,false).get("dispatch_state"));responseMode="OK";assertEquals("FAILED",service.submit("QM",p,false).get("dispatch_state"));assertEquals(1,creates.get());assertEquals("ACCEPTED",service.submit("QM",p,true).get("dispatch_state"));assertEquals(2,creates.get());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_task",Integer.class));}
    @Test void duplicateOrderRejectionIsUnknownAndQueriesOnly(){setupWarehouse("QIMEN");Map<String,Object> p=payload();responseMode="DUPLICATE";assertEquals("UNKNOWN",service.submit("QM",p,false).get("dispatch_state"));service.submit("QM",p,true);assertEquals(1,creates.get());assertEquals("ACCEPTED",service.query("QM","FH_TEST").get("dispatch_state"));}
    @Test void changedSnapshotsAndBoundConnectionTargetsCannotBeOverwritten(){setupWarehouse("QIMEN");Map<String,Object> p=payload();service.submit("QM",p,false);p.put("warehouse_carrier_code","OTHER");assertThrows(IllegalArgumentException.class,()->service.submit("QM",p,true));Map<String,Object> c=connections.list("QM").get(0);c.put("endpoint","https://different.invalid");assertThrows(IllegalArgumentException.class,()->connections.save("QM",c));assertEquals(1,creates.get());}
    @Test void disabledOrVirtualWarehouseAndTenantMismatchRejectBeforeSending(){setupWarehouse("QIMEN");Map<String,Object> p=payload();jdbc.update("UPDATE wms_simulation_store_info SET outbound_mode=2");assertThrows(IllegalArgumentException.class,()->service.resolve("QM",p));assertThrows(IllegalArgumentException.class,()->service.resolve("OTHER",p));jdbc.update("UPDATE wms_simulation_store_info SET outbound_mode=1");jdbc.update("UPDATE wms_connection SET enabled=0");assertThrows(IllegalArgumentException.class,()->service.resolve("QM",p));assertEquals(0,creates.get());}
    @Test void concurrentSubmissionClaimsOneExternalCreate() throws Exception {setupWarehouse("QIMEN");Map<String,Object> p=payload();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Map<String,Object>>> jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();return service.submit("QM",p,false);}));start.countDown();for(Future<?> job:jobs)job.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertEquals(1,creates.get());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_task",Integer.class));assertEquals("ACCEPTED",service.status("QM","FH_TEST").get("dispatch_state"));assertNull(failure.get());}
    @Test void warehouseDeliveredStatusNeverCreatesLocalShipmentOrReceiptAmounts(){setupWarehouse("QIMEN");Map<String,Object> p=payload();service.submit("QM",p,false);queryMode="DELIVERED";Map<String,Object> state=service.query("QM","FH_TEST");assertEquals("ACCEPTED",state.get("dispatch_state"));assertTrue(text(state.get("query_message")).contains("完整出库明细"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM wms_receipt_line",Integer.class));}
    @Test void failedQueryDoesNotEraseEarlierAcceptanceOrReportNewConfirmation(){setupWarehouse("QIMEN");Map<String,Object> p=payload();service.submit("QM",p,false);queryMode="NOT_FOUND";Map<String,Object> state=service.query("QM","FH_TEST");assertEquals("ACCEPTED",state.get("dispatch_state"));assertEquals(false,state.get("query_success"));assertTrue(text(state.get("query_message")).contains("查无单据"));assertEquals(1,creates.get());}
    @Test void createSummaryRemainsVisibleWhenQueriesPushCreationOffFirstPage(){
        setupWarehouse("QIMEN");service.submit("QM",payload(),false);WmsInteractionLog logs=context.getBean(WmsInteractionLog.class);
        for(int i=0;i<55;i++){long key=logs.start("QM",connection,1L,"FH_TEST","OUT","OUTBOUND_QUERY","");logs.finish(key,"UNKNOWN","","fixture query",1);}
        assertTrue(logs.list("QM","FH_TEST",1).stream().allMatch(r->"OUTBOUND_QUERY".equals(r.get("action"))));
        assertEquals(1,logs.list("QM","FH_TEST",1,"OUTBOUND_CREATE","").size());assertEquals(0,logs.list("QM","FH_TEST",1,"OUTBOUND_CREATE","FAILED").size());
        Map<String,Object> summary=logs.summary("QM","FH_TEST");assertEquals(56,id(summary.get("total")));Map<String,Object> first=(Map<String,Object>)summary.get("first_create");assertEquals("OUTBOUND_CREATE",first.get("action"));assertEquals("SUCCESS",first.get("result"));assertFalse(first.containsKey("request_body"));assertEquals(first,summary.get("latest_create"));
        long retried=logs.start("QM",connection,1L,"FH_TEST","OUT","OUTBOUND_CREATE","");logs.finish(retried,"SUCCESS","","retry fixture",1);assertEquals(id(first.get("id")),id(((Map<?,?>)logs.summary("QM","FH_TEST").get("first_create")).get("id")));assertEquals(retried,id(((Map<?,?>)logs.summary("QM","FH_TEST").get("latest_create")).get("id")));
        assertNull(logs.summary("OTHER","FH_TEST").get("first_create"));assertEquals(0,id(logs.summary("OTHER","FH_TEST").get("total")));assertTrue(logs.list("OTHER","FH_TEST",1,"OUTBOUND_CREATE","").isEmpty());
        assertThrows(IllegalArgumentException.class,()->logs.list("QM","FH_TEST",1,"UNKNOWN_ACTION",""));assertThrows(IllegalArgumentException.class,()->logs.list("QM","FH_TEST",1,"","INVALID"));
    }
}
